// CDLADVANCEBLOCKLookback returns how many leading bars [Core.CDLADVANCEBLOCK]
// consumes before its first value: called with startIdx 0, its first value is
// at that bar.
func (c *Core) CDLADVANCEBLOCKLookback() (int, error) {
	lookback := c.cdladvanceblockLookback()
	if lookback < 0 {
		return 0, BadParam
	}
	return int(lookback), nil
}

// CDLADVANCEBLOCKDisplayShift returns how many bars ahead (positive) or behind
// (negative) of the bar that computed it a chart draws output outputIdx of
// [Core.CDLADVANCEBLOCK]. The values are never shifted.
//
// Every output of this function is drawn at its own bar, so the answer is 0.
//
// It takes the output's position among the outputs of [Core.CDLADVANCEBLOCK],
// from 0, and returns [BadParam] for an index that names no output.
func (c *Core) CDLADVANCEBLOCKDisplayShift(outputIdx int) (int, error) {
	if outputIdx < 0 || outputIdx >= 1 {
		return 0, BadParam
	}
	return 0, nil
}

// CDLADVANCEBLOCK recognizes the Advance Block pattern over bars startIdx
// through endIdx.
//
// Three-candle bearish reversal pattern: three white candles with consecutively
// higher closes whose advance weakens (progressively smaller bodies and/or
// lengthening upper shadows). Signals that an uptrend's advance is being
// blocked. A hit (-100) is bearish: the advance is stalling/blocked; meaningful
// mainly within an existing uptrend.
//
// Formula and more info at https://ta-lib.org/functions/cdladvanceblock.
//
// Inputs, each at least endIdx+1 long:
//   - inOpen: Open price of each bar.
//   - inHigh: High price of each bar.
//   - inLow: Low price of each bar.
//   - inClose: Close price of each bar.
//
// Outputs, each at least as long as the values written (the input length always
// suffices):
//   - outInteger: -100 on a detected pattern (always bearish), 0 otherwise;
//     never emits +100.
//
// Element k of each output is the value at bar BegIdx+k of the returned
// [OutRange], and BegIdx is at least [Core.CDLADVANCEBLOCKLookback]: a range
// that ends before it returns NBElement 0.
//
// The error is [OutOfRangeStartIndex] or [OutOfRangeEndIndex] for a range
// outside 0 to [IndexMax] or ending before it starts, and [BadParam] for an
// input too short or an output empty or too short.
func (c *Core) CDLADVANCEBLOCK(startIdx, endIdx int, inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (OutRange, error) {
	if startIdx < 0 || startIdx > IndexMax {
		return OutRange{}, OutOfRangeStartIndex
	}
	if endIdx < 0 || endIdx > IndexMax || endIdx < startIdx {
		return OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdladvanceblockLookback())
	if lookback < 0 {
		return OutRange{}, BadParam
	}
	if len(inOpen) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inHigh) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inLow) < endIdx+1 {
		return OutRange{}, BadParam
	}
	if len(inClose) < endIdx+1 {
		return OutRange{}, BadParam
	}
	outLen := requiredOut(startIdx, endIdx, lookback)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	if retCode := c.cdladvanceblockImpl(int32(startIdx), int32(endIdx), inOpen, inHigh, inLow, inClose, &outBegIdx, &outNBElement, outInteger); retCode != Success {
		return OutRange{}, retCode
	}
	return OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}

