// OutRange returns the bars the stream has a value for, as
// [Core.CDLADVANCEBLOCK] reports them over the same bars; each Update and each
// Advance adds one to NBElement.
func (sp *CDLADVANCEBLOCKStream) OutRange() OutRange {
	return OutRange{BegIdx: sp.outRangeBegIdx, NBElement: sp.outRangeCount}
}

// Advance counts one bar the stream was not fed: OutRange grows by one and
// Value keeps its previous answer. It returns [OutOfRangeEndIndex] once
// OutRange reaches bar [IndexMax].
func (sp *CDLADVANCEBLOCKStream) Advance() error {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return OutOfRangeEndIndex
	}
	sp.outRangeCount++
	return nil
}

// Update commits one closed bar (inOpen, inHigh, inLow and inClose) and returns
// the new value. It returns [BadParam] for a bar value that is not finite and
// [OutOfRangeEndIndex] once OutRange reaches bar [IndexMax], both before
// anything changes.
func (sp *CDLADVANCEBLOCKStream) Update(inOpen, inHigh, inLow, inClose float64) (int32, error) {
	if sp.outRangeBegIdx+sp.outRangeCount > IndexMax {
		return 0, OutOfRangeEndIndex
	}
	if !isFinite(inOpen) || !isFinite(inHigh) || !isFinite(inLow) || !isFinite(inClose) {
		return 0, BadParam
	}
	cdladvanceblockStepImpl(sp, inOpen, inHigh, inLow, inClose)
	sp.outRangeCount++
	return sp.cur_outInteger, nil
}

